from pathlib import Path
import json,html
root=Path(__file__).resolve().parents[1]
titles=['De precios dispersos a una decisión','SQL para hacer preguntas precisas','Bronze: conservar y consultar','Silver: datos comparables y gobernados','Gold: una canasta defendible','Del dashboard a la acción','GenAI y evidencia bajo evaluación','Comité de decisión']
lessons=['Entorno GCP, arquitectura moderna y pregunta propia.','SELECT, filtros, agregaciones, joins y vigencias.','Ingesta, manifiesto, tabla externa y escala.','Calidad, reconciliación, accesos y responsabilidades.','Modelo analítico, cobertura, costo y KPIs.','Visualización, filtros y comunicación ejecutiva.','Recuperación, citas, memo y revisión humana.','Defensa, auditoría cruzada y cierre de recursos.']
editorial=json.loads((root/'editorial/manifest.json').read_text())
counts=[editorial.get(str(i),{}).get('slides',28 if i<8 else 14) for i in range(1,9)]
for key,data in editorial.items(): titles[int(key)-1]=data['title']
total=sum(counts)
cards=''.join(f'<article class="course-card"><span class="eyebrow">SESIÓN {i:02d} · 180 MIN</span><h2>{html.escape(t)}</h2><p>{lessons[i-1]}</p><div><a class="open-deck" href="especialidad-{i:02d}/">Abrir deck ↗</a><a href="especialidad-{i:02d}/laboratorio.html">Guía y entregable</a></div><small>{counts[i-1]} slides · H{i}{' · rediseño editorial' if str(i) in editorial else ''}</small></article>' for i,t in enumerate(titles,1))
(root/'index.html').write_text('''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Big Data · Especialidad</title><meta name="description" content="Ocho sesiones interactivas de Especialidad: teoría, laboratorio y proyecto propio."><link rel="stylesheet" href="compartido/curso.css"></head><body><header><a class="brand" href="./"><span class="mark">∴</span> Big Data <span class="edition">ESPECIALIDAD · 24 HORAS</span></a><nav><a href="README.md">Guía de uso</a><a href="piloto/">Piloto original</a></nav></header><main class="course-home"><p class="eyebrow">SISTEMAS DE DATOS DISTRIBUIDOS · OCHO SESIONES</p><h1>Una decisión merece<br><em>evidencia.</em></h1><p class="lead">Comprender la arquitectura. Consultar con criterio.<br>Comunicar evidencia que se puede comprobar.</p><div class="course-contract"><p><b>Aprendemos con un ejemplo</b><br>employees para SQL y precios ilustrativos para Medallion.</p><p><b>Defendemos proyectos distintos</b><br>Cada equipo usa otro dataset, una pregunta y KPIs propios.</p></div><p class="lead">Revisión editorial: sesiones 1–7 con el kit de Chema.<br>Las sesiones 8 conservan la versión base.</p><p class="lead"><a href="clase-bigquery/">Clase independiente: BigQuery, arquitecturas y Medallion · 3 horas ↗</a></p><div class="course-grid">'''+cards+'''</div><p class="source">'''+str(total)+''' slides · navegación por clic y teclado · guías imprimibles · recursos descargables.<br>Material local de revisión. Los ejercicios ilustrativos no prueban hallazgos sobre PROFECO ni ejecución a gran escala. Las guías GCP requieren ensayo con cuenta de alumno.</p></main></body></html>''')
(root/'manifest.json').write_text(json.dumps({'track':'especialidad','sessions':[{'id':i,'title':t,'url':f'especialidad-{i:02d}/','slides':counts[i-1],'minutes':180} for i,t in enumerate(titles,1)],'slides':total,'cloudValidated':False},ensure_ascii=False,indent=2)+'\n')
print('Índice local y manifiesto de ocho sesiones generados.')
